/* printf → USART2 (monitor seriale a 115200) */
int __io_putchar(int ch)
{
  HAL_UART_Transmit(&huart2, (uint8_t *)&ch, 1, HAL_MAX_DELAY);
  return ch;
}

/* TIM3 conta a 1 MHz (84 MHz / 84): Pulse = durata dell'impulso in µs */
static void servo_gradi(int g)
{
  __HAL_TIM_SET_COMPARE(&htim3, TIM_CHANNEL_1, 1000 + g * 1000 / 180);
}

/* USER CODE END 0 */

/**
  * @brief  The application entry point.
  * @retval int
  */
int main(void)
{

  /* USER CODE BEGIN 1 */

  /* USER CODE END 1 */

  /* MCU Configuration--------------------------------------------------------*/

  /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
  HAL_Init();

  /* USER CODE BEGIN Init */

  /* USER CODE END Init */

  /* Configure the system clock */
  SystemClock_Config();

  /* USER CODE BEGIN SysInit */

  /* USER CODE END SysInit */

  /* Initialize all configured peripherals */
  MX_GPIO_Init();
  MX_USART2_UART_Init();
  MX_TIM3_Init();
  /* USER CODE BEGIN 2 */
  HAL_TIM_PWM_Start(&htim3, TIM_CHANNEL_1);
  int g = 0, passo = 10;

  /* USER CODE END 2 */

  /* Infinite loop */
  /* USER CODE BEGIN WHILE */
  while (1)
  {
    /* USER CODE END WHILE */

    /* USER CODE BEGIN 3 */
    servo_gradi(g);
    printf("Angolo: %d gradi (impulso %d us)\r\n", g, 1000 + g * 1000 / 180);
    HAL_Delay(200);
    g += passo;
    if (g >= 180 || g <= 0) passo = -passo;
  }
  /* USER CODE END 3 */
}

